                ObjectType::Page,
                Page::"Qlty. Management Setup Guide",
                "Assisted Setup Group"::DoMoreWithBC,
                '',
                "Video Category"::Extensions,
                'https://go.microsoft.com/fwlink/?linkid=2338953',
                true);
    end;

